rule.example:
// Bad
private Object execute(String seat, String document) { ... }

// Good
private GqlTTDResponse execute(String seat, String document) { ... }

// Bad
String refusalReason(String seat) {
    if (allowed(seat)) return null;
    return "seat is read-only";
}

// Good
SeatVerdict isWritable(String seat) {
    return allowed(seat) ? SeatVerdict.writable()
                         : SeatVerdict.refused("seat is read-only");
}
